suggestions:
handle(failure: unknown): boolean {
  const errorCode = this.errorCode(failure);
  if (errorCode === STEP_UP_REQUIRED) {
    const alreadyOpen = this.open();
    this.code = '';
    this.open.set(true);
    return !alreadyOpen;
  }
  if (errorCode === INVALID_CODE) {
    this.code = '';
  }
  return false;
}

value(): string | undefined {
  return this.open() ? this.code.trim() || undefined : undefined;
}

private fail(failure: unknown): void {
  if (this.pending() && this.prompt.handle(failure)) return;
  this.error.set(this.problems.message(failure));
}
